//! Partial campaign display. Scientific source provenance stays in code only.
use anyhow::Result;use rustplotlib::*;use std::{path::Path,fs};
fn main()->Result<()>{let a:Vec<_>=std::env::args().collect();let f=hdf5::File::open(&a[1])?;let z=f.dataset("nominal_altitude_km")?.read_raw::<f64>()?;let out=Path::new(&a[2]);fs::create_dir_all(out)?;
let mut fig=Figure::new(IntendedUse::ArticleWide);fig.width_mm=190.;fig.height_mm=270.;fig.latex.cache=out.join("latex-cache");
let mut ye=vec![75.];ye.extend(z.windows(2).map(|p|(p[0]+p[1])/2.));ye.push(1025.);
for(q,(key,label,lim,norm))in[("electron_density_m3","Electron density (m$^{-3}$), empirical",[1e10,1e12],Normalization::Log),("ion_temperature_k","Ion temperature (K)",[150.,3000.],Normalization::Linear),("electron_temperature_k","Electron temperature (K)",[150.,6000.],Normalization::Linear),("spectral_velocity_m_s","Spectral velocity (m/s)",[-1000.,1000.],Normalization::Linear)].iter().enumerate(){
let scale=fig.scale(Scale::new(*lim,*norm,ColorMap::turbo())?);let mut ax=Axes::new([7.5,8.0],[100.,1000.],if q==3{"Local time (UTC+8), 6 October 2025"}else{""},"Altitude (km)");ax.xticks=vec![7.5,7.75,8.];ax.xticklabels=Some(vec!["07:30".into(),"07:45".into(),"08:00".into()]);ax.yticks=vec![100.,300.,500.,700.,1000.];let rect=Rect::new(23.,22.+q as f64*58.,130.,36.);let mut p=Panel::new(rect,ax);p.pcolormesh(vec![7.5,8.],ye.clone(),f.dataset(key)?.read_raw::<f64>()?,scale)?;fig.panels.push(p);let mut bar=Colorbar::new(Rect::new(25.,rect.y+40.,126.,2.),scale,*label,vec![lim[0],lim[1]]);bar.horizontal=true;fig.colorbars.push(bar);}
fig.labels.push(Label::new("SYISR zenith: completed 30-minute window (partial campaign)",95.,7.));fig.labels.push(Label::new("180.2 s on-beam; provisional gates retained; latest exposure 07:55:56 local",95.,262.));fig.save(out.join("progress-zenith-time-altitude.png"))?;Ok(())}
